import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.CWgsre3x.js";const u=JSON.parse('{"title":"Flight & ferry arrival intelligence","description":"","frontmatter":{},"headers":[],"relativePath":"plus/arrival-intelligence.md","filePath":"plus/arrival-intelligence.md"}'),n={name:"plus/arrival-intelligence.md"};function l(o,e,s,d,c,p){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="flight-ferry-arrival-intelligence" tabindex="-1">Flight &amp; ferry arrival intelligence <a class="header-anchor" href="#flight-ferry-arrival-intelligence" aria-label="Permalink to &quot;Flight &amp; ferry arrival intelligence&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Source-reviewed against TransferBook+ v0.7.26. Verify the installed release, company, permissions and configuration. Use authorized synthetic data for training. Commercial activation is not asserted.</p></div><h2 id="review-the-arrival-board" tabindex="-1">Review the arrival board <a class="header-anchor" href="#review-the-arrival-board" aria-label="Permalink to &quot;Review the arrival board&quot;">​</a></h2><ol><li>Select the authorized company and operating hub. Locate the reservation and correct outbound or return leg in Arrival Intelligence.</li><li>Verify carrier/service number, date, departure and destination against an approved source. Record the transport identity and a manual observation with the time and supporting evidence. Do not invent estimated or actual arrival times.</li><li>Inspect the reported early, delayed, cancelled or disrupted status. Review the observation history and any generated dispatch advisory. Superseded or expired evidence must not be used to approve a new decision.</li><li>Approve or reject a proposed pickup adjustment only with dispatch permission. Verify the proposed timing against assignment conflicts, full journey duration, chauffeur availability, vehicle maintenance and tariff date/night boundaries. Where tariff review is required, resolve it before proceeding.</li><li>Reopen the reservation and relevant schedule. Verify the decision, independent leg timing and chauffeur arrival brief. A completed advisory decision must not be reversed by resubmitting it.</li></ol><h2 id="availability-and-fallback" tabindex="-1">Availability and fallback <a class="header-anchor" href="#availability-and-fallback" aria-label="Permalink to &quot;Availability and fallback&quot;">​</a></h2><p>Manual observation and advisory history are persistent. Automated external tracking, background scheduling, complete provider quota enforcement and licensed map activation remain outstanding. A provider configuration entry is not a live feed. Continue approved manual verification if no external provider is available. Do not treat advisory information as a guarantee of transport arrival.</p><p>See <a href="/plus/dispatch-schedule.html">Dispatch schedule</a> and <a href="/integrations/maps-arrivals-setup.html">Maps and arrival API setup</a>.</p>',7)])])}const h=a(n,[["render",l]]);export{u as __pageData,h as default};
